import { betterAuth } from 'better-auth'
import { drizzleAdapter } from 'better-auth/adapters/drizzle'
import { db } from './db'
import * as schema from './db/schema'

const isProduction = process.env.NODE_ENV === 'production'
const authSecret =
  process.env.BETTER_AUTH_SECRET ||
  'dev-only-change-me-shopee-pricing-desk-secret-32-chars'

if (isProduction && !process.env.BETTER_AUTH_SECRET) {
  console.warn('BETTER_AUTH_SECRET should be set before running in production.')
}

const nextDevOrigins = Array.from({ length: 7 }, (_, index) => 3000 + index).flatMap(
  (port) => [`http://localhost:${port}`, `http://127.0.0.1:${port}`],
)
const trustedOrigins = process.env.BETTER_AUTH_TRUSTED_ORIGINS
  ? process.env.BETTER_AUTH_TRUSTED_ORIGINS.split(',')
      .map((origin) => origin.trim())
      .filter(Boolean)
  : nextDevOrigins

export const auth = betterAuth({
  appName: 'Shopee Pricing Desk',
  baseURL:
    process.env.BETTER_AUTH_URL ||
    process.env.NEXT_PUBLIC_AUTH_BASE_URL ||
    'http://localhost:3000',
  secret: authSecret,
  trustedOrigins,
  database: drizzleAdapter(db, {
    provider: 'pg',
    schema,
  }),
  emailAndPassword: {
    enabled: true,
    autoSignIn: true,
  },
  user: {
    additionalFields: {
      role: {
        type: 'string',
        required: false,
        defaultValue: 'user',
        input: false,
      },
    },
  },
})
